<script setup>
import { ref } from 'vue'
import { appState, login, logout, enterDemo, synchronize, chooseConflict, exportLocal } from '../state/app.js'
import { business } from '../sync/engine.js'
const email = ref(''), password = ref(''), busy = ref(false), showLogin = ref(false)
async function signIn() { busy.value = true; try { await login(email.value, password.value); if (appState.mode === 'account') showLogin.value = false } finally { password.value = ''; busy.value = false } }
function differences(record) {
  const local = business(record.local), remote = business(record.remote ?? {})
  return [...new Set([...Object.keys(local), ...Object.keys(remote)])].filter(key => key !== 'id' && JSON.stringify(local[key]) !== JSON.stringify(remote[key])).map(key => ({ key, local: local[key] ?? '—', remote: remote[key] ?? '—' }))
}
</script>
<template>
  <section v-if="appState.mode === 'login' || showLogin" class="card" aria-labelledby="login-title"><h2 id="login-title">Accedi al tuo spazio</h2><form @submit.prevent="signIn"><label>Email<input v-model="email" type="email" autocomplete="username" required /></label><label>Password<input v-model="password" type="password" autocomplete="current-password" required /></label><button class="primary" :disabled="busy || appState.offline">{{ busy ? 'Accesso…' : 'Accedi' }}</button></form><p class="small">Usa l’account già creato. La password non viene conservata dall’app.</p><button v-if="appState.mode === 'login'" @click="enterDemo">Apri la demo locale</button><button v-else @click="showLogin = false">Annulla</button></section>
  <section v-if="appState.mode !== 'login'" class="card account-panel"><div class="row"><strong>{{ appState.mode === 'demo' ? 'Demo locale' : appState.email || 'Account personale' }}</strong><button :disabled="appState.syncing || appState.saving" @click="logout">{{ appState.mode === 'demo' ? 'Vai al login' : 'Esci' }}</button></div>
    <template v-if="appState.mode === 'account'"><p class="small">I dati sono salvati subito sul dispositivo. Sincronizza per inviare tutte le modifiche e scaricare gli aggiornamenti.</p><button class="primary full" :disabled="appState.syncing || appState.offline || appState.saving" @click="synchronize(true)">{{ appState.syncing ? 'Sincronizzazione…' : appState.snapshot.sync?.lastDownload ? 'Sincronizza' : 'Scarica le tue schede' }}</button>
      <p class="small">Ultimo invio: {{ appState.snapshot.sync?.lastUpload ? new Date(appState.snapshot.sync.lastUpload).toLocaleString('it-IT') : 'nessuno' }}<br />Ultimo download: {{ appState.snapshot.sync?.lastDownload ? new Date(appState.snapshot.sync.lastDownload).toLocaleString('it-IT') : 'nessuno' }}</p><button @click="showLogin = !showLogin">Accedi nuovamente</button>
      <details v-if="appState.snapshot.outbox.length"><summary>{{ appState.snapshot.outbox.length }} gruppi in attesa</summary><p v-for="group in appState.snapshot.outbox" :key="group.operation_id" class="small">{{ group.kind.replaceAll('_', ' ') }} · {{ group.status === 'conflict' ? 'conflitto' : group.authorized ? 'invio automatico' : 'invio manuale' }}<span v-if="group.error"> · {{ group.error }}</span></p></details>
      <article v-for="group in appState.snapshot.outbox.filter(g => g.status === 'conflict')" :key="group.operation_id" class="conflict"><h3>Due versioni da confrontare</h3><p>Scegli per l’intero gruppo. Le modifiche successive collegate sono incluse nella scelta. Prima puoi esportare una copia.</p><details v-for="record in group.conflict" :key="record.table + record.id"><summary>{{ record.local.nome || record.table.replaceAll('_', ' ') }} · {{ record.id.slice(0, 8) }}</summary><div class="conflict-scroll"><table><thead><tr><th>Campo</th><th>Dispositivo</th><th>Online</th></tr></thead><tbody><tr v-for="difference in differences(record)" :key="difference.key"><td>{{ difference.key }}</td><td>{{ difference.local }}</td><td>{{ difference.remote }}</td></tr></tbody></table></div></details><button :disabled="appState.syncing || appState.saving" @click="chooseConflict(group.operation_id, 'local')">Conserva locale, invia poi con Sincronizza</button><button :disabled="appState.syncing || appState.saving" @click="chooseConflict(group.operation_id, 'remote')">Usa la versione online</button></article>
    </template><button @click="exportLocal">Esporta copia locale e modifiche in attesa</button>
  </section>
</template>
